import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";
import { createStep, decodeRecipe, encodeRecipe, runRecipe } from "../lib/recipe-utils.ts";
import { disassemblePickle, normalizePhpInput, parsePhpSerialized, phpClasses, phpFromJson, phpToJson, serializePhp } from "../lib/serialization-utils.ts";

const text = (value) => new TextEncoder().encode(value);
const decode = (bytes) => new TextDecoder().decode(bytes);

// Generated by PHP 8 serialize(): protected/private properties, a nested array, a reference and an enum.
const phpObject = 'a:4:{i:0;O:4:"User":8:{s:4:"name";s:5:"guest";s:7:"\0*\0role";s:4:"user";s:8:"\0User\0id";i:7;s:4:"tags";a:2:{i:0;s:1:"a";i:1;s:6:"中文";}s:1:"f";d:1.5;s:1:"n";N;s:1:"b";b:1;s:4:"self";r:2;}s:1:"k";i:-3;i:10;s:1:"x";s:6:"nested";a:1:{s:4:"deep";a:2:{i:0;i:1;i:1;i:2;}}}';

test("PHP serialize data round-trips through the editable JSON form, keeping key order", () => {
  const value = parsePhpSerialized(phpObject);
  assert.equal(serializePhp(value), phpObject);
  const json = phpToJson(value);
  assert.ok(json.indexOf('"k"') < json.indexOf('"10"'));
  assert.equal(serializePhp(phpFromJson(json)), phpObject);
  assert.deepEqual(phpClasses(value), ["User"]);
  assert.equal(serializePhp(parsePhpSerialized('E:11:"Suit:Hearts";')), 'E:11:"Suit:Hearts";');
  assert.equal(serializePhp(phpFromJson('{"0": 2.0, "1": -0.5}')), "a:2:{i:0;d:2;i:1;d:-0.5;}");
});

test("PHP edits recompute UTF-8 string lengths and bad input is rejected with a position", () => {
  const edited = phpFromJson('{"__class__": "User", "name": "管理員", "isAdmin": true}');
  assert.equal(serializePhp(edited), 'O:4:"User":2:{s:4:"name";s:9:"管理員";s:7:"isAdmin";b:1;}');
  assert.throws(() => parsePhpSerialized('s:5:"abc";'), /位置 \d+：宣告長度 5/);
  assert.throws(() => parsePhpSerialized('a:1:{i:0;s:1:"x";'), /位置/);
  assert.throws(() => phpFromJson('{"a": }'), /JSON 第/);
  assert.equal(normalizePhpInput(encodeURIComponent('O:4:"User":0:{}')).decoded, "URL decode");
  assert.equal(normalizePhpInput(btoa('a:1:{i:0;s:1:"x";}')).text, 'a:1:{i:0;s:1:"x";}');
});

test("pickle disassembly matches pickletools.genops for protocols 0–5", async () => {
  const cases = JSON.parse(await readFile(new URL("./e2e/fixtures/pickletools-reference.json", import.meta.url), "utf8"));
  assert.equal(cases.length, 12);
  for (const item of cases) {
    const report = disassemblePickle(Uint8Array.from(Buffer.from(item.b64, "base64")));
    assert.deepEqual(report.ops.map((op) => [op.name, op.offset]), item.ops, `protocol ${item.p} ${item.name}`);
    assert.equal(report.complete, true);
    const high = report.imports.filter((entry) => entry.risk === "high").map((entry) => `${entry.module}.${entry.name}`);
    assert.deepEqual(high, item.name === "evil" ? ["posix.system"] : [], `protocol ${item.p} ${item.name}`);
  }
  assert.throws(() => disassemblePickle(new Uint8Array([0xff, 0x00])), /未知的 opcode/);
  assert.equal(disassemblePickle(text("(lp0\n")).complete, false);
});

test("recipes chain operations, stop at the first failure and survive share links", async () => {
  const input = text("654a784c79306c4d7279354b54633473534931507a6b6a4d7a4d764d533438767a792f4b4c713446414a74654330413d");
  const steps = ["from-hex", "from-base64", "inflate"].map(createStep);
  const results = await runRecipe(input, steps);
  assert.equal(decode(results[2].output), "flag{recipe_chaining_works}");
  const xor = { ...createStep("xor"), args: { key: "2a", format: "hex" } };
  const masked = await runRecipe(text("flag"), [xor, createStep("to-hex"), createStep("from-hex"), xor]);
  assert.equal(decode(masked[3].output), "flag");
  assert.equal(decode((await runRecipe(text("synt{ebg}"), [createStep("rot13")]))[0].output), "flag{rot}");
  assert.equal(decode((await runRecipe(text("a%20b+c%2Fd"), [createStep("url-decode")]))[0].output), "a b c/d");
  const failed = await runRecipe(text("not hex!"), steps);
  assert.match(failed[0].error, /Hex/);
  assert.deepEqual(failed.slice(1).map((result) => result.output), [null, null]);
  const disabled = await runRecipe(text("abc"), [{ ...createStep("reverse"), disabled: true }, createStep("upper")]);
  assert.equal(decode(disabled[1].output), "ABC");
  const shared = decodeRecipe(encodeRecipe([xor, { ...createStep("rot13"), disabled: true }]));
  assert.deepEqual(shared, [xor, { ...createStep("rot13"), disabled: true }]);
  assert.throws(() => decodeRecipe("not-json"), /Recipe/);
  assert.deepEqual(decodeRecipe(encodeRecipe([{ op: "eval", args: {} }])), []);
});
